/**
 * Residential build, R5 (integration 13): who hears a customer's reply as a push, and when. The tech who has it hears at
 * once. The office hears after a wait the owner sets (15 minutes to start) when nobody has answered by then, and first
 * after hours. A legal-line reply goes to the office alone. The after state is card 13 of
 * `customer-messages-integrations-mockups.html` on branch spike/gc-mode. Pure: `messages-notify` (the function that
 * already pushes the clause approvals) will call it with a new body shape, send each push that is due, and record it.
 *
 * A push is sent and recorded as the notify functions do today: web-push `{ title, body, url, tag }` to each of the
 * person's `push_subscriptions`, then one `notification_history` row per person (`pushSentRow`). That row carries the
 * line it was for in `message_id`, a nullable column R5's SQL PR adds, so no line is pushed twice.
 *
 * Punch list #141 PR 3 (v2.6029): a person's own hours (`pushHours.ts`, `user_push_hours`) hold a push for them, and the
 * planner writes the held row (`pushHeldRows`, `channel = 'held'`). Here the hand-on: when whoever has the reply is off
 * at the line's time, the office hears at once with who is off and until when (`holderOffWords`), and the holder's own
 * push is held; the holder still has the conversation on Messages. When the office is the Customers seat alone and the
 * seat is off, a push to the office widens to the office roles who are on at the push's time.
 */
import { firstName } from '../contacts/names.ts'
import { GC_MESSAGES_HREF } from '../gc/links.ts'
import { backAt, holderOffWords, NO_PUSH_HOURS, pushedNow, type PushHoursByUser } from './pushHours.ts'
import type { ThreadMessage } from './thread.ts'

/** The `app_settings` key for the wait before the office hears (minutes), added by R5's SQL PR. */
export const OFFICE_WAIT_KEY = 'messages_office_wait_minutes'
export const OFFICE_WAIT_MINUTES = 15

/**
 * The hour is the measure (`weekStrip.ts`, Answered within an hour): when nobody has answered this many minutes in,
 * whoever has it hears once more — the office when nobody has it (v2.5875). Ten minutes leave time to answer inside
 * the hour. Never after hours: the `nobody` branch sends no breach push, so no phone buzzes at night.
 */
export const BREACH_MINUTES = 50

/**
 * Who has the reply: `whoHasReply`'s answer (`hasRule.ts`, #5561), or `routeReply`'s for a legal line (`legalLines.ts`),
 * whose `reason` is `legal`. Written out as the fields this reads, until #5561 lands and this becomes its `Pick`.
 */
export interface ReplyHas {
  has: 'tech' | 'office' | 'nobody'
  userId: string | null
  name: string | null
  reason: string
  /** After hours: `send` when the app answers this one, `sent` when it already answered tonight. */
  autoAnswer?: 'send' | 'sent' | null
}

/** A line that came in, with who sent it. `kind` is the contact's, read as a string so R0's new kinds need no change here. */
export type ReplyLine = Pick<ThreadMessage, 'id' | 'contactId' | 'channel' | 'direction' | 'at' | 'body' | 'subject'> & {
  name: string
  goesBy?: string | null
  kind: string
}

export interface NotifySettings {
  /** `messages_office_wait_minutes`. */
  officeWaitMinutes?: number
  /** The office, as the function resolves it: the Customers seat's teammate, else the office team. */
  officeUserIds: readonly string[]
  /** The office roles' users, whom a push widens to when the seat alone is off (#141 PR 3). `officeUserIds` when not given. */
  officeRoleUserIds?: readonly string[]
  /** Each person's push hours (`user_push_hours`); no entry, or none given, is any time. */
  pushHours?: PushHoursByUser
}

/**
 * The push to whoever has it, at once; the office's, after the wait; the holder's once more as the hour nears; and the
 * office's at once when the holder is off (#141 PR 3).
 */
export type PushTemplate = 'message_reply' | 'message_reply_wait' | 'message_reply_breach' | 'message_reply_off'

export interface Push {
  messageId: string
  contactId: string
  audience: 'tech' | 'office'
  userIds: string[]
  title: string
  body: string
  /** The thread at the line. Null for a tech until Job Mode's thread has a URL (R5's screens). */
  url: string | null
  /** One per person on the device, so a second line replaces the first. */
  tag: string
  template: PushTemplate
  /** When it is due, ISO. */
  dueAt: string
  /** The office's push after the wait: dropped when someone answered first (`answeredBefore`). */
  cancelIfAnswered: boolean
}

/** A `notification_history` row as the notify functions write one, with the line it was for; `held` for a push a person's hours kept (#141 PR 3). */
export interface PushSentRow {
  recipient_user_id: string
  template_type: PushTemplate
  title: string
  body_preview: string
  channel: 'push' | 'held'
  message_id: string
}

/** A person a due push was held for (#141 PR 3): off until `backAt`, ISO. The row goes in with `channel = 'held'` and no push. */
export interface HeldPush {
  push: Push
  userId: string
  backAt: string | null
}

/** Kinds whose lines never push: a supply house's and a candidate's (R0), which Follow up leaves out too. */
const QUIET_KINDS: ReadonlySet<string> = new Set(['supply_house', 'candidate'])

/** The lines that push: a text, an email, a portal write, a voicemail and a missed call. An answered call does not. */
export const PUSH_CHANNELS: ReadonlySet<string> = new Set(['text', 'email', 'portal', 'voicemail', 'missed'])

const BODY_MAX = 140

/** The office's link: the thread at the line, over the Messages view. */
export function threadUrl(contactId: string, messageId: string): string {
  return `${GC_MESSAGES_HREF}&thread=${encodeURIComponent(contactId)}&at=${encodeURIComponent(messageId)}`
}

function first(line: ReplyLine): string {
  return firstName({ name: line.name, goesBy: line.goesBy, kind: line.kind === 'unknown' ? 'unknown' : undefined }) || line.name
}

/** What they said, as the push's body: their own words, cut to fit. */
export function replyWords(line: Pick<ReplyLine, 'channel' | 'body' | 'subject'>): string {
  const said = (line.channel === 'email' ? line.subject?.trim() || line.body : line.body).replace(/\s+/g, ' ').trim()
  if (said) return said.length > BODY_MAX ? `${said.slice(0, BODY_MAX - 1).trimEnd()}…` : said
  if (line.channel === 'missed') return 'Called and nobody picked up.'
  if (line.channel === 'voicemail') return 'Left a voicemail.'
  return 'Wrote to us.'
}

/** "Nobody answered Dana in 15 minutes. It is on Needs a reply." */
export function officeWaitWords(name: string, minutes: number): string {
  return `Nobody answered ${name} in ${minutes} ${minutes === 1 ? 'minute' : 'minutes'}. It is on Needs a reply.`
}

/** "Dana has waited 50 minutes and nobody has answered. The hour is close." */
export function breachWords(name: string, minutes: number): string {
  return `${name} has waited ${minutes} minutes and nobody has answered. The hour is close.`
}

/**
 * "Dana wrote after hours. The app answered with the hours we open." Null while no after-hours answer goes (until
 * `quo-send` sends one): then the words say only what is true, that the line waits for the morning.
 */
export function afterHoursWords(name: string, autoAnswer: ReplyHas['autoAnswer']): string {
  if (autoAnswer === 'send') return `${name} wrote after hours. The app answered with the hours we open.`
  if (autoAnswer === 'sent') return `${name} wrote after hours. The app already answered tonight.`
  return `${name} wrote after hours. It waits for the morning.`
}

const plus = (iso: string, minutes: number) => new Date(Date.parse(iso) + minutes * 60_000).toISOString()

/**
 * The pushes one line that came in should make, each with its due time. To the tech who has it at once, with the
 * office after the wait. To the office's seat pick at once, with the rest of the office after the wait. To the office
 * after the wait when nobody has it. To whoever has it once more at `BREACH_MINUTES` when still nobody has answered,
 * the whole office when nobody is named (v2.5875). To the office at once after hours, and for a legal-line reply, with
 * no one else. None for a supply house or a candidate, and none already sent for this line (`sent`).
 *
 * A person's hours (#141 PR 3): when whoever has it is off at the line's time, the office hears at once too, with who
 * is off and until when, then their words (`message_reply_off`); the holder's own push stays in the list for the
 * planner to hold. A push to the office that is the seat alone, and the seat off at the push's time, widens to the
 * office roles who are on then; with none on it stays with the seat, held.
 */
export function pushesFor(
  inbound: ReplyLine,
  has: ReplyHas,
  settings: NotifySettings,
  sent: ReadonlyArray<Pick<PushSentRow, 'message_id' | 'template_type'>> = [],
): Push[] {
  if (inbound.direction !== 'in' || !PUSH_CHANNELS.has(inbound.channel) || QUIET_KINDS.has(inbound.kind)) return []
  const wait = Math.max(0, Math.round(settings.officeWaitMinutes ?? OFFICE_WAIT_MINUTES))
  const office = [...new Set(settings.officeUserIds)]
  const roles = [...new Set(settings.officeRoleUserIds ?? settings.officeUserIds)]
  const hours = settings.pushHours ?? NO_PUSH_HOURS
  const on = (id: string, at: string) => pushedNow(at, hours.get(id) ?? null)
  /** The office at `at`, `but` the holder: the seat alone and off widens to the office roles who are on. */
  const officeAt = (at: string, but: string | null): string[] => {
    const named = office.filter((id) => id !== but)
    if (office.length === 1 && !on(office[0]!, at)) {
      const wide = roles.filter((id) => id !== but && on(id, at))
      if (wide.length > 0) return wide
    }
    return named
  }
  const name = first(inbound)
  const link = threadUrl(inbound.contactId, inbound.id)
  const base = { messageId: inbound.id, contactId: inbound.contactId, title: inbound.name, tag: `messages-${inbound.contactId}` }
  const now = (audience: Push['audience'], userIds: string[], body: string, url: string | null): Push => ({
    ...base,
    audience,
    userIds,
    body,
    url,
    template: 'message_reply',
    dueAt: inbound.at,
    cancelIfAnswered: false,
  })
  const later = (but: string | null): Push => {
    const dueAt = plus(inbound.at, wait)
    return {
      ...base,
      audience: 'office',
      userIds: officeAt(dueAt, but),
      body: officeWaitWords(name, wait),
      url: link,
      template: 'message_reply_wait',
      dueAt,
      cancelIfAnswered: true,
    }
  }
  const breach = (audience: Push['audience'], userIds: string[], url: string | null): Push => ({
    ...base,
    audience,
    userIds,
    body: breachWords(name, BREACH_MINUTES),
    url,
    template: 'message_reply_breach',
    dueAt: plus(inbound.at, BREACH_MINUTES),
    cancelIfAnswered: true,
  })
  /** The office's push at once when the holder is off: who is off, until when, then the words. Nothing while the holder is on. */
  const handOn = (holderId: string): Push[] => {
    const holderHours = hours.get(holderId) ?? null
    if (pushedNow(inbound.at, holderHours)) return []
    const holder = has.name?.trim() ? firstName({ name: has.name }) : 'a teammate'
    return [{ ...now('office', officeAt(inbound.at, holderId), `${holderOffWords(name, holder, backAt(inbound.at, holderHours), inbound.at)} ${replyWords(inbound)}`, link), template: 'message_reply_off' }]
  }
  const breachDue = plus(inbound.at, BREACH_MINUTES)

  let pushes: Push[]
  if (has.reason === 'legal') {
    pushes = has.userId ? [now('office', [has.userId], replyWords(inbound), link), ...handOn(has.userId)] : [now('office', officeAt(inbound.at, null), replyWords(inbound), link)]
  } else if (has.has === 'tech' && has.userId) {
    pushes = [now('tech', [has.userId], replyWords(inbound), null), ...handOn(has.userId), later(has.userId), breach('tech', [has.userId], null)]
  } else if (has.has === 'office') {
    pushes = has.userId
      ? [now('office', [has.userId], replyWords(inbound), link), ...handOn(has.userId), later(has.userId), breach('office', [has.userId], link)]
      : [later(null), breach('office', officeAt(breachDue, null), link)]
  } else {
    pushes = [now('office', officeAt(inbound.at, null), afterHoursWords(name, has.autoAnswer ?? null), link)]
  }
  const done = new Set(sent.filter((s) => s.message_id === inbound.id).map((s) => s.template_type))
  return pushes.filter((p) => p.userIds.length > 0 && !done.has(p.template))
}

/** Whether a push's time has come. */
export function pushDue(push: Pick<Push, 'dueAt'>, now: string): boolean {
  return Date.parse(now) >= Date.parse(push.dueAt)
}

/**
 * Whether someone answered the person after this line came in, by `by` when it is given: a text, an email or a call
 * from us. A team note or an event is not an answer, and neither is a text the app sent on its own (`auto`, v2.6012:
 * the text back after a missed call). It drops the office's push after the wait.
 */
export function answeredBefore(
  line: Pick<ThreadMessage, 'contactId' | 'at'>,
  outs: ReadonlyArray<Pick<ThreadMessage, 'contactId' | 'channel' | 'direction' | 'at' | 'auto'>>,
  by?: string,
): boolean {
  const from = Date.parse(line.at)
  const until = by ? Date.parse(by) : Infinity
  return outs.some((m) => {
    if (m.contactId !== line.contactId || m.direction !== 'out' || m.auto) return false
    if (m.channel !== 'text' && m.channel !== 'email' && m.channel !== 'call') return false
    const t = Date.parse(m.at)
    return t > from && t <= until
  })
}

const rowOf = (push: Push, userId: string, channel: PushSentRow['channel']): PushSentRow => ({
  recipient_user_id: userId,
  template_type: push.template,
  title: push.title,
  body_preview: push.body.slice(0, 200),
  channel,
  message_id: push.messageId,
})

/** The `notification_history` rows a sent push writes: one per person it reached. */
export function pushSentRow(push: Push, reached: readonly string[] = push.userIds): PushSentRow[] {
  return reached.map((id) => rowOf(push, id, 'push'))
}

/** The rows the held people get (#141 PR 3): the push as it would have gone, `channel = 'held'`, so the line is never pushed to them later and the Dashboard can list it. */
export function pushHeldRows(held: readonly HeldPush[]): PushSentRow[] {
  return held.map(({ push, userId }) => rowOf(push, userId, 'held'))
}
